cd multicode/duckpit/build/par3/k-S/Assets/Game/Code/OnePit; python3 -I - <<'EOF'
p='Core/OnePitBalance.Goal.cs'
t=open(p,encoding='utf8').read()
old=t[t.index('        /// Товар главы (подписи)'):t.index('        /// Значок товара главы')]
new='''        /// Слово «утка» по числу — ЕДИНСТВЕННАЯ функция склонения: «1 утка · 4 утки · 5 уток · 21 утка · 11 уток».
        /// nominative=false — винительный («ещё 31 утку в Яму», «бросай 1 утку»); true — «В Яме 31 утка».
        public static string DuckWord(int n, bool nominative = false) =>
            Pitt.Meta.MetaTuning.Plural(n, nominative ? "утка" : "утку", "утки", "уток");

        static readonly System.Text.RegularExpressions.Regex _duckTagRx =
            new System.Text.RegularExpressions.Regex("(\\\\d[\\\\d \\u00a0]*)?\\\\s*" + System.Text.RegularExpressions.Regex.Escape(Pitt.UI.U.DuckTag));

        /// Значок утки в строке → слово, склонённое по числу перед значком («ещё 4 🦆» → «ещё 4 утки»; числа нет — «уток»).
        /// Для подписей в мире и замков листа, где спрайта утки нет в шрифте.
        public static string DuckTagToWord(string s)
        {
            if (string.IsNullOrEmpty(s) || s.IndexOf(Pitt.UI.U.DuckTag, System.StringComparison.Ordinal) < 0) return s;
            return _duckTagRx.Replace(s, m =>
            {
                if (!m.Groups[1].Success) return "уток";
                string digits = m.Groups[1].Value.Replace(" ", "").Replace("\\u00a0", "");
                return int.TryParse(digits, out int n) ? m.Groups[1].Value + " " + DuckWord(n) : m.Groups[1].Value + " уток";
            });
        }

        /// Товар главы (подписи): «уток», «мячей», «КЕ железа», …  nominative — для «В Яме N …».
        public static string GoalUnit(int chapter, int n, bool nominative = false)
        {
            switch (chapter)
            {
                case 1: return DuckWord(n, nominative);
                case 2: return Pitt.Meta.MetaTuning.Plural(n, "мяч", "мяча", "мячей");
                case 3: return "железа";
                case 4: return nominative ? Pitt.Meta.MetaTuning.Plural(n, "золотая утка", "золотые утки", "золотых уток")
                                          : Pitt.Meta.MetaTuning.Plural(n, "золотую утку", "золотые утки", "золотых уток");
                default: return Pitt.Meta.MetaTuning.Plural(n, "фонарь", "фонаря", "фонарей");
            }
        }

'''
t=t.replace(old,new)
open(p,'w',encoding='utf8').write(t)
EOF
